@RunWith(RobolectricTestRunner.class) @Config(sdk=34,manifest=Config.NONE) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class RogueCombatV234Test {
 final ScreenMagicV201Test h=new ScreenMagicV201Test();
 @Before public void setup(){h.setup();}
 RuntimeState state()throws Exception{RuntimeState s=new RuntimeState();s.rpg().restoreProgression(99,0);s.rpg().restoreStats(100,100,100,100,100,0);s.rpg().restoreBaseResources(100000,100000);s.applyDerivedGrowth();s.player().hp=100000;s.player().mp=50000;s.player().x=s.player().y=0;((List<?>)h.field(s,"monsters")).clear();return s;}
 RuntimeState.Monster add(RuntimeState s,String id,float x,float y)throws Exception{RuntimeState.Monster m=new RuntimeState.Monster(id,"V234",x,y,1000000,"B");((List<RuntimeState.Monster>)h.field(s,"monsters")).add(m);return m;}
 RuntimeCombatSession session(RuntimeState s,CharacterRenderer.Direction d){RuntimeCombatSession c=new RuntimeCombatSession(s,(a,t)->true,(a,id)->true,a->true);c.setPlayerFacing(()->d);return c;}
 @Test public void shurikenFourFacingsFirstFourCellsOnlyAndNoPiercing()throws Exception{
  for(CharacterRenderer.Direction d:CharacterRenderer.Direction.values())for(int n=1;n<=5;n++){
   RuntimeState s=state();float[] step=MartialSkillPolicy.step(d);RuntimeState.Monster m=add(s,"front",step[0]*n,step[1]*n);RuntimeCombatSession c=session(s,d);CombatActionOrchestrator.Submission result=c.submitFacingShuriken();assertEquals(d+" cells"+n,n<=4,result.accepted());if(n<=4){List<CombatResolver.Event> events=c.tick(.2f).events;assertTrue(m.hp<m.maxHp);assertEquals(1,events.stream().filter(e->e.type==CombatResolver.EventType.HIT_FEEDBACK&&e.amount>0).count());}else assertEquals(0,c.cooldownRemaining("player",RogueSkillPolicy.SHURIKEN),0);
  }
  RuntimeState s=state();RuntimeState.Monster far=add(s,"far",128,64),near=add(s,"near",32,16),side=add(s,"side",0,32);RuntimeCombatSession c=session(s,CharacterRenderer.Direction.SE);assertFalse(c.submitPlayer(far.id,RogueSkillPolicy.SHURIKEN).accepted());assertEquals(near.id,c.submitFacingShuriken().targetId);c.tick(.2f);assertTrue(near.hp<near.maxHp);assertEquals(far.maxHp,far.hp);assertEquals(side.maxHp,side.hp);
  for(float[] at:new float[][]{{-32,-16},{0,32},{64,0},{0,0}}){s=state();add(s,"illegal",at[0],at[1]);assertFalse(session(s,CharacterRenderer.Direction.SE).submitFacingShuriken().accepted());}
 }
 @Test public void shurikenRechecksNearestLiveDirectionWallAndVisibilityAtContact()throws Exception{
  RuntimeState s=state();RuntimeState.Monster far=add(s,"far",128,64);RuntimeCombatSession c=session(s,CharacterRenderer.Direction.SE);assertTrue(c.submitFacingShuriken().accepted());RuntimeState.Monster near=add(s,"new-near",32,16);c.tick(.2f);assertEquals(far.maxHp,far.hp);assertEquals(near.maxHp,near.hp);
  s=state();RuntimeState.Monster m=add(s,"blocked",32,16);c=new RuntimeCombatSession(s,(a,t)->false,(a,id)->true,a->true);c.setPlayerFacing(()->CharacterRenderer.Direction.SE);assertFalse(c.submitFacingShuriken().accepted());assertEquals(0,c.cooldownRemaining("player",RogueSkillPolicy.SHURIKEN),0);
  c=session(s,CharacterRenderer.Direction.SE);c.setSkillVisibility(id->false);assertFalse(c.submitFacingShuriken().accepted());
 }
 GameView actor(String id)throws Exception{
  GameView v=new GameView(h.c);v.layout(0,0,960,540);v.setSkillTestMode(false);RuntimeState s=h.field(v,"state");s.rpg().restoreProgression(99,0);s.rpg().restoreJobCode("ROGUE");s.rpg().restoreStats(100,100,100,100,100,0);s.rpg().restoreBaseResources(100000,100000);s.applyDerivedGrowth();s.player().hp=100000;s.player().mp=50000;((List<?>)h.field(s,"monsters")).clear();WorldRuntimeAdapter w=h.field(v,"worldAdapter");List<WorldMoveTargetController.TileCenter> tiles=new ArrayList<>(w.navigationTiles());tiles.sort(Comparator.comparingDouble(t->Math.hypot(t.x-WorldDef.PLAYER_SPAWN_X,t.y-WorldDef.PLAYER_SPAWN_Y)));boolean placed=false;
  for(WorldMoveTargetController.TileCenter t:tiles)if(w.canPlayerOccupy(t.x,t.y)&&w.canPlayerOccupy(t.x+32,t.y+16)&&w.hasLineOfSight(t.x,t.y,t.x+32,t.y+16)){s.player().x=t.x;s.player().y=t.y;placed=true;break;}assertTrue(placed);RuntimeState.Monster m=add(s,"rogue-damage-target",s.player().x+32,s.player().y+16);w.snapCameraToPlayer();((CombatController)h.field(v,"combat")).selectTarget(m);((CanonicalActorFacing)h.field(v,"playerFacing")).setLocomotion(CharacterRenderer.Direction.SE);SkillBook b=h.field(v,"skillBook");assertTrue(b.learn(id,100));assertTrue(b.assign(0,id));RuntimeCombatSession c=h.field(v,"combatSession");RuntimeCombatPortAdapter port=h.field(c,"port");port.abilities.random=()->.99;s.skillEffects().put("player",RogueSkillPolicy.SENSE,"STEALTH",1,30);return v;
 }
 void tap(GameView v)throws Exception{RectF r=(RectF)h.call(v,"slotRect",new Class<?>[]{int.class},0);h.tap(v,r.centerX(),r.centerY());}
 @Test public void everyRogueDamageQuickslotChargesAndActuallySubtractsItsOwnComputedDamageWithMatchingPopup()throws Exception{
  JSONArray trace=new JSONArray();Set<Integer> values=new HashSet<>();
  for(String n:new String[]{"001","003","007","014","015","020","021","022","023","027","028","029","030"}){
   h.setup();String id="SK_도적_"+n;GameView v=actor(id);RuntimeState s=h.field(v,"state");RuntimeCombatSession c=h.field(v,"combatSession");RuntimeState.Monster m=s.monsters().get(0);FinalStats stats=s.rpg().finalStats().withEffects(s.skillEffects(),"player");SkillAbilityCatalog.Ability a=SkillAbilityCatalog.get(id);int hpBefore=s.player().hp,mpBefore=s.player().mp;int raw=(int)Math.round(a.formula.equals("ASSASSIN")?hpBefore*.6336:a.formula.equals("ASSASSIN_PLUS")?hpBefore*.95:a.formula.equals("BASIC")?stats.prototypePhysicalAttack():(stats.weaponBaseAttack()+1.8*stats.str+2.2*stats.dex+stats.dam)*a.coefficient);int expected=CombatStatPipeline.resolveSkill(raw,CombatStatPipeline.Channel.PHYSICAL,stats,FinalStats.neutral(100,0)).applied;
   tap(v);assertTrue(id,c.playerActionActive());float hit=c.effectiveCastSeconds(id);h.call(v,"tickSkillCombat",new Class<?>[]{float.class},hit-.01f);assertEquals(id,m.maxHp,m.hp);h.call(v,"tickSkillCombat",new Class<?>[]{float.class},.011f);assertEquals(id,expected,m.maxHp-m.hp);assertEquals(id,expected,m.lastDamage);assertTrue(m.damagePopupClock>0);assertEquals(id,mpBefore-c.effectiveMpCost(id),s.player().mp);assertEquals(id,a.resourceBurst()?10000:hpBefore,s.player().hp);values.add(expected);trace.put(new JSONObject().put("id",id).put("raw",raw).put("applied",expected).put("hpBefore",m.maxHp).put("hpAfter",m.hp).put("damagePopup",m.lastDamage).put("casterHpBefore",hpBefore).put("casterHpAfter",s.player().hp).put("testMode",false));h.capture(v,"v234-damage-"+n);
   SkillVfxRenderer fx=h.field(v,"skillVfx");assertFalse(id+" no shared impact repaint over original skill colours",fx.pulses.stream().anyMatch(p->p.sheet.equals("impact")));if(n.equals("003"))assertTrue(fx.pulses.isEmpty());
  }assertTrue(values.size()>6);File f=new File("build/reports/device-review/v234-rogue-damage-trace.json");f.getParentFile().mkdirs();try(FileOutputStream out=new FileOutputStream(f)){out.write(trace.toString(2).getBytes(java.nio.charset.StandardCharsets.UTF_8));}
 }
 @Test public void shurikenNormalInputIgnoresSelectedFartherTargetAndNeverApproachesOrTurns()throws Exception{
  GameView v=actor(RogueSkillPolicy.SHURIKEN);RuntimeState s=h.field(v,"state");RuntimeState.Monster near=s.monsters().get(0),far=add(s,"selected-far",s.player().x+128,s.player().y+64);((CombatController)h.field(v,"combat")).selectTarget(far);float x=s.player().x,y=s.player().y;tap(v);assertNull(((SkillApproachController)h.field(v,"skillApproach")).skillId);RuntimeCombatSession c=h.field(v,"combatSession");h.call(v,"tickSkillCombat",new Class<?>[]{float.class},.2f);assertTrue(near.hp<near.maxHp);assertEquals(far.maxHp,far.hp);assertEquals(x,s.player().x,0);assertEquals(y,s.player().y,0);assertEquals(CharacterRenderer.Direction.SE,((CanonicalActorFacing)h.field(v,"playerFacing")).presentation());
 }
 @Test public void shurikenBehindSelectedMonsterDoesNotQueueWalkingOrCharge()throws Exception{
  GameView v=actor(RogueSkillPolicy.SHURIKEN);RuntimeState s=h.field(v,"state");RuntimeState.Monster m=s.monsters().get(0);m.x=s.player().x-32;m.y=s.player().y-16;float x=s.player().x,y=s.player().y;int hp=m.hp,mp=s.player().mp;tap(v);RuntimeCombatSession c=h.field(v,"combatSession");assertFalse(c.playerActionActive());assertNull(((SkillApproachController)h.field(v,"skillApproach")).skillId);assertEquals(0,c.cooldownRemaining("player",RogueSkillPolicy.SHURIKEN),0);assertEquals(hp,m.hp);assertEquals(mp,s.player().mp);assertEquals(x,s.player().x,0);assertEquals(y,s.player().y,0);
 }
 @Test public void labelledBlueAmbushAndDistinctSourceColoursReachNativeWithoutCommonImpact()throws Exception{
  ClassicSkillReference r=new ClassicSkillReference(h.c,"rogue");assertNotNull(r.channel("SK_도적_015",false));Bitmap grid=Bitmap.createBitmap(1200,400,Bitmap.Config.ARGB_8888);Canvas out=new Canvas(grid);out.drawColor(0xff303930);int k=0;
  for(String n:new String[]{"007","014","015","021","022","023","028","029","030"}){ClassicSkillReference.Channel ch=r.channel("SK_도적_"+n,false);CapturedSkillFx.Sequence s=ch.sequence;int coloured=0,elapsed=0,bestTime=0;long best=0;
   for(int frame=0;frame<s.durations.length;frame++){long energy=0;for(int y=0;y<s.height;y++)for(int x=0;x<s.width;x++){int c=s.atlas.getPixel(frame%s.columns*s.width+x,frame/s.columns*s.height+y);energy+=Color.alpha(c);if(Color.alpha(c)>30){int red=Color.red(c),g=Color.green(c),b=Color.blue(c);if(n.equals("015")&&b>red+30&&g>red+20||n.equals("021")&&g>red+20&&b>red+20||n.equals("022")&&b>g+20&&red>g+20||n.equals("023")&&red>b+20&&g>b+10||n.equals("007")&&red>g+20&&b>g+20)coloured++;}}if(energy>best){best=energy;bestTime=elapsed+s.durations[frame]/2;}elapsed+=s.durations[frame];}
   if(Arrays.asList("007","015","021","022").contains(n))assertTrue(n+" source hue",coloured>100);if(n.equals("023"))assertTrue(coloured>15);r.draw(out,ch,bestTime/1000f,70+k%5*235,100+k/5*190);k++;
  }RogueRepairV232Test.save(grid,"v234-per-skill-original-colours");CapturedSkillFx cap=new CapturedSkillFx(h.c);CapturedSkillFx.Sequence s=cap.get("SK_도적_027");int blue=0;for(int y=0;y<s.atlas.getHeight();y++)for(int x=0;x<s.atlas.getWidth();x++){int c=s.atlas.getPixel(x,y);if(Color.alpha(c)>30&&Color.blue(c)>Color.red(c)+30&&Color.green(c)>Color.red(c)+20)blue++;}assertTrue("original blue finisher phase must survive warm mask",blue>100);
  Bitmap b=Bitmap.createBitmap(1200,480,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);c.drawColor(0xff303930);Paint p=new Paint();for(int i=0;i<6;i++){float age=new float[]{.04f,.17f,.3f,.57f,.7f,.9f}[i];cap.draw(c,p,"SK_도적_020",age,80+i*190,180);cap.draw(c,p,"SK_도적_027",new float[]{.04f,.2f,.5f,.94f,1.15f,1.55f}[i],80+i*190,400);}RogueRepairV232Test.save(b,"v234-clean-assassin-no-capture-actor");
 }
}
